export interface ManagedTimer {
  schedule(ms: number, fn: () => void): void;
  cancel(): void;
}

export function createManagedTimer(): ManagedTimer {
  let handle: ReturnType<typeof setTimeout> | null = null;
  return {
    schedule(ms, fn) {
      if (handle !== null) clearTimeout(handle);
      handle = setTimeout(() => {
        handle = null;
        fn();
      }, ms);
    },
    cancel() {
      if (handle !== null) {
        clearTimeout(handle);
        handle = null;
      }
    },
  };
}

